-- Errata reading for O11: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, payload FROM records WHERE stream='pharmacy_dispenses'), b AS (SELECT DISTINCT patient FROM (SELECT patient, lower(json_extract(payload,'$.medication_name')) m FROM r WHERE json_extract(payload,'$.status')='dispensed') WHERE m LIKE '%diphenhydramine%' OR m LIKE '%chlorpheniramine%' OR m LIKE '%diazepam%' OR m LIKE '%lorazepam%' OR m LIKE '%clonazepam%' OR m LIKE '%alprazolam%' OR m LIKE '%meperidine%' OR m LIKE '%cyclobenzaprine%') SELECT COUNT(*) AS count FROM patients p JOIN b ON b.patient=p.id WHERE coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported'))>=65;
